var vmStackPool = sync.Pool{
	New: func() any {
		s := make([]uint64, 1024)
		return &s
	},
}

func readLEB128uGen(data []byte, pos *int) uint32 {
	var res uint32
	var shift uint
	for {
		b := data[*pos]
		*pos++
		res |= uint32(b&0x7f) << shift
		if b&0x80 == 0 {
			break
		}
		shift += 7
	}
	return res
}

func readLEB128sGen(data []byte, pos *int) int64 {
	var res int64
	var shift uint
	var b byte
	for {
		b = data[*pos]
		*pos++
		res |= int64(b&0x7f) << shift
		shift += 7
		if b&0x80 == 0 {
			break
		}
	}
	if shift < 64 && (b&0x40) != 0 {
		res |= -(1 << shift)
	}
	return res
}

func skipOpcode(code []byte, pos *int) {
	op := code[*pos]
	*pos++
	switch op {
	case 0x02, 0x03, 0x04: // block, loop, if
		*pos++ // blocktype
	case 0x0c, 0x0d: // br, br_if
		_ = readLEB128uGen(code, pos)
	case 0x0e: // br_table
		cnt := readLEB128uGen(code, pos)
		for i := uint32(0); i <= cnt; i++ {
			_ = readLEB128uGen(code, pos)
		}
	case 0x10: // call
		_ = readLEB128uGen(code, pos)
	case 0x11: // call_indirect
		_ = readLEB128uGen(code, pos)
		*pos++ // tableidx
	case 0x20, 0x21, 0x22: // local.get, local.set, local.tee
		_ = readLEB128uGen(code, pos)
	case 0x23, 0x24: // global.get, global.set
		_ = readLEB128uGen(code, pos)
	case 0x28, 0x29, 0x2a, 0x2b, 0x2c, 0x2d, 0x2e, 0x2f,
		0x30, 0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37,
		0x38, 0x39, 0x3a, 0x3b, 0x3c, 0x3d, 0x3e: // memory load/store
		_ = readLEB128uGen(code, pos) // align
		_ = readLEB128uGen(code, pos) // offset
	case 0x3f, 0x40: // memory.size, memory.grow
		*pos++
	case 0x41: // i32.const
		_ = readLEB128sGen(code, pos)
	case 0x42: // i64.const
		_ = readLEB128sGen(code, pos)
	case 0x43: // f32.const
		*pos += 4
	case 0x44: // f64.const
		*pos += 8
	case 0xfc: // saturating float or memory operations
		sub := readLEB128uGen(code, pos)
		if sub == 10 || sub == 11 { // memory.fill, memory.copy
			*pos += 2
		}
	}
}

func ensureMem(needed int) {
	if needed > len(mem) {
		newCap := len(mem) * 2
		if newCap < needed {
			newCap = needed + 65536*16
		}
		newMem := make([]byte, newCap)
		copy(newMem, mem)
		mem = newMem
	}
}

func execWasm(fnIdx uint32, args ...uint64) uint64 {
	codeIdx := fnIdx - wasmNumImports
	if int(codeIdx) >= len(wasmCode) {
		return 0
	}
	code := wasmCode[codeIdx]
	pos := 0

	// Parse local counts
	localCntVec := readLEB128uGen(code, &pos)
	totalLocals := wasmFuncParamCnt[fnIdx]
	for l := uint32(0); l < localCntVec; l++ {
		count := readLEB128uGen(code, &pos)
		pos++ // valType
		totalLocals += int(count)
	}

	var locals [512]uint64
	copy(locals[:], args)

	spPtr := vmStackPool.Get().(*[]uint64)
	valStack := *spPtr
	sp := 0

	type blockFrame struct {
		kind byte // 2=block, 3=loop, 4=if, 5=else
		startPos int
		stackLen int
	}
	var controlStack [64]blockFrame
	csp := 0

	// Outer function block
	controlStack[0] = blockFrame{kind: 2, startPos: pos, stackLen: 0}
	csp = 1

	for pos < len(code) {
		op := code[pos]
		pos++

		switch op {
		case 0x00: // Bug 1 fix: 0x00 is unreachable
			panic("wasm unreachable executed")
		case 0x01: // Bug 1 fix: 0x01 is nop
			// do nothing
		case 0x02, 0x03, 0x04: // block, loop, if
			pos++ // blocktype
			controlStack[csp] = blockFrame{kind: op, startPos: pos, stackLen: sp}
			csp++
			if op == 0x04 { // if
				sp--
				cond := valStack[sp]
				if uint32(cond) == 0 {
					// Skip to else or end
					depth := 1
					for pos < len(code) && depth > 0 {
						o := code[pos]
						if o == 0x02 || o == 0x03 || o == 0x04 {
							depth++
						} else if o == 0x05 {
							if depth == 1 {
								depth = 0
								skipOpcode(code, &pos)
								break
							}
						} else if o == 0x0b {
							depth--
							if depth == 0 {
								skipOpcode(code, &pos)
								break
							}
						}
						skipOpcode(code, &pos)
					}
				}
			}
		case 0x05: // else
			// Skip to end of if/else
			depth := 1
			for pos < len(code) && depth > 0 {
				o := code[pos]
				if o == 0x02 || o == 0x03 || o == 0x04 {
					depth++
				} else if o == 0x0b {
					depth--
					if depth == 0 {
						skipOpcode(code, &pos)
						break
					}
				}
				skipOpcode(code, &pos)
			}
		case 0x0b: // end
			if csp > 0 {
				csp--
			}
		case 0x0c: // br (with stack unwinding)
			depth := int(readLEB128uGen(code, &pos))
			if depth < csp {
				target := controlStack[csp-1-depth]
				var topVal uint64
				hasVal := false
				if sp > target.stackLen {
					topVal = valStack[sp-1]
					hasVal = true
				}
				sp = target.stackLen
				if hasVal {
					valStack[sp] = topVal
					sp++
				}
				if target.kind == 0x03 { // loop
					pos = target.startPos
				} else {
					// Skip to end of target block
					d := depth + 1
					for pos < len(code) && d > 0 {
						o := code[pos]
						if o == 0x02 || o == 0x03 || o == 0x04 {
							d++
						} else if o == 0x0b {
							d--
							if d == 0 {
								skipOpcode(code, &pos)
								break
							}
						}
						skipOpcode(code, &pos)
					}
				}
			} else {
				vmStackPool.Put(spPtr)
				if sp > 0 { return valStack[sp-1] }
				return 0
			}
		case 0x0d: // br_if (with stack unwinding)
			depth := int(readLEB128uGen(code, &pos))
			sp--
			cond := valStack[sp]
			if cond != 0 {
				if depth < csp {
					target := controlStack[csp-1-depth]
					var topVal uint64
					hasVal := false
					if sp > target.stackLen {
						topVal = valStack[sp-1]
						hasVal = true
					}
					sp = target.stackLen
					if hasVal {
						valStack[sp] = topVal
						sp++
					}
					if target.kind == 0x03 {
						pos = target.startPos
					} else {
						d := depth + 1
						for pos < len(code) && d > 0 {
							o := code[pos]
							if o == 0x02 || o == 0x03 || o == 0x04 {
								d++
							} else if o == 0x0b {
								d--
								if d == 0 {
									skipOpcode(code, &pos)
									break
								}
							}
							skipOpcode(code, &pos)
						}
					}
				} else {
					vmStackPool.Put(spPtr)
					if sp > 0 { return valStack[sp-1] }
					return 0
				}
			}
		case 0x0e: // br_table (with stack unwinding)
			cnt := int(readLEB128uGen(code, &pos))
			var targets []int
			for i := 0; i < cnt; i++ {
				targets = append(targets, int(readLEB128uGen(code, &pos)))
			}
			defTarget := int(readLEB128uGen(code, &pos))
			sp--
			idx := int(valStack[sp])
			chosenTarget := defTarget
			if idx >= 0 && idx < len(targets) {
				chosenTarget = targets[idx]
			}
			if chosenTarget < csp {
				target := controlStack[csp-1-chosenTarget]
				var topVal uint64
				hasVal := false
				if sp > target.stackLen {
					topVal = valStack[sp-1]
					hasVal = true
				}
				sp = target.stackLen
				if hasVal {
					valStack[sp] = topVal
					sp++
				}
				if target.kind == 0x03 {
					pos = target.startPos
				} else {
					d := chosenTarget + 1
					for pos < len(code) && d > 0 {
						o := code[pos]
						if o == 0x02 || o == 0x03 || o == 0x04 {
							d++
						} else if o == 0x0b {
							d--
							if d == 0 {
								skipOpcode(code, &pos)
								break
							}
						}
						skipOpcode(code, &pos)
					}
				}
			}
		case 0x0f: // return
			vmStackPool.Put(spPtr)
			if sp > 0 { return valStack[sp-1] }
			return 0
		case 0x10: // call (Bug 4 fix: zero alloc call args)
			targetIdx := readLEB128uGen(code, &pos)
			pCnt := wasmFuncParamCnt[targetIdx]
			var callArgsBuf [16]uint64
			callArgs := callArgsBuf[:pCnt]
			for i := pCnt - 1; i >= 0; i-- {
				sp--
				callArgs[i] = valStack[sp]
			}
			res := execWasm(targetIdx, callArgs...)
			if wasmFuncRetCnt[targetIdx] > 0 {
				valStack[sp] = res
				sp++
			}
		case 0x11: // call_indirect (Bug 4 fix: zero alloc call args)
			_ = readLEB128uGen(code, &pos)
			pos++ // tableIdx
			sp--
			tblIdx := valStack[sp]
			targetIdx := funcTable[tblIdx]
			pCnt := wasmFuncParamCnt[targetIdx]
			var callArgsBuf [16]uint64
			callArgs := callArgsBuf[:pCnt]
			for i := pCnt - 1; i >= 0; i-- {
				sp--
				callArgs[i] = valStack[sp]
			}
			res := execWasm(targetIdx, callArgs...)
			if wasmFuncRetCnt[targetIdx] > 0 {
				valStack[sp] = res
				sp++
			}
		case 0x1a: // drop
			sp--
		case 0x1b: // select
			sp--
			c := valStack[sp]
			sp--
			val2 := valStack[sp]
			sp--
			val1 := valStack[sp]
			if c != 0 { valStack[sp] = val1 } else { valStack[sp] = val2 }
			sp++
		case 0x20: // local.get
			idx := readLEB128uGen(code, &pos)
			valStack[sp] = locals[idx]
			sp++
		case 0x21: // local.set
			idx := readLEB128uGen(code, &pos)
			sp--
			locals[idx] = valStack[sp]
		case 0x22: // local.tee
			idx := readLEB128uGen(code, &pos)
			locals[idx] = valStack[sp-1]
		case 0x23: // global.get
			idx := readLEB128uGen(code, &pos)
			valStack[sp] = wasmGlobals[idx]
			sp++
		case 0x24: // global.set
			idx := readLEB128uGen(code, &pos)
			sp--
			wasmGlobals[idx] = valStack[sp]
		case 0x28: // i32.load
			pos++ // align
			off := readLEB128uGen(code, &pos)
			sp--
			ptr := valStack[sp]
			addr := int(uint32(ptr) + off)
			ensureMem(addr + 4)
			valStack[sp] = uint64(binary.LittleEndian.Uint32(mem[addr:]))
			sp++
		case 0x29: // i64.load
			pos++
			off := readLEB128uGen(code, &pos)
			sp--
			ptr := valStack[sp]
			addr := int(uint32(ptr) + off)
			ensureMem(addr + 8)
			valStack[sp] = binary.LittleEndian.Uint64(mem[addr:])
			sp++
		case 0x2c: // i32.load8_u
			pos++
			off := readLEB128uGen(code, &pos)
			sp--
			ptr := valStack[sp]
			addr := int(uint32(ptr) + off)
			ensureMem(addr + 1)
			valStack[sp] = uint64(mem[addr])
			sp++
		case 0x2d: // i32.load8_s
			pos++
			off := readLEB128uGen(code, &pos)
			sp--
			ptr := valStack[sp]
			addr := int(uint32(ptr) + off)
			ensureMem(addr + 1)
			valStack[sp] = uint64(uint32(int8(mem[addr])))
			sp++
		case 0x2e: // i32.load16_s
			pos++
			off := readLEB128uGen(code, &pos)
			sp--
			ptr := valStack[sp]
			addr := int(uint32(ptr) + off)
			ensureMem(addr + 2)
			valStack[sp] = uint64(uint32(int16(binary.LittleEndian.Uint16(mem[addr:]))))
			sp++
		case 0x2f: // i32.load16_u
			pos++
			off := readLEB128uGen(code, &pos)
			sp--
			ptr := valStack[sp]
			addr := int(uint32(ptr) + off)
			ensureMem(addr + 2)
			valStack[sp] = uint64(binary.LittleEndian.Uint16(mem[addr:]))
			sp++
		case 0x36: // i32.store
			pos++
			off := readLEB128uGen(code, &pos)
			sp--
			v := valStack[sp]
			sp--
			ptr := valStack[sp]
			addr := int(uint32(ptr) + off)
			ensureMem(addr + 4)
			binary.LittleEndian.PutUint32(mem[addr:], uint32(v))
		case 0x37: // i64.store
			pos++
			off := readLEB128uGen(code, &pos)
			sp--
			v := valStack[sp]
			sp--
			ptr := valStack[sp]
			addr := int(uint32(ptr) + off)
			ensureMem(addr + 8)
			binary.LittleEndian.PutUint64(mem[addr:], v)
		case 0x3a: // i32.store8
			pos++
			off := readLEB128uGen(code, &pos)
			sp--
			v := valStack[sp]
			sp--
			ptr := valStack[sp]
			addr := int(uint32(ptr) + off)
			ensureMem(addr + 1)
			mem[addr] = byte(v)
		case 0x3b: // i32.store16
			pos++
			off := readLEB128uGen(code, &pos)
			sp--
			v := valStack[sp]
			sp--
			ptr := valStack[sp]
			addr := int(uint32(ptr) + off)
			ensureMem(addr + 2)
			binary.LittleEndian.PutUint16(mem[addr:], uint16(v))
		case 0x3f: // memory.size
			pos++
			valStack[sp] = uint64(len(mem) / 65536)
			sp++
		case 0x40: // memory.grow
			pos++
			sp--
			valStack[sp] = uint64(len(mem) / 65536)
			sp++
		case 0x41: // i32.const
			v := readLEB128sGen(code, &pos)
			valStack[sp] = uint64(uint32(v))
			sp++
		case 0x42: // i64.const
			v := readLEB128sGen(code, &pos)
			valStack[sp] = uint64(v)
			sp++
		case 0x45: // i32.eqz
			sp--
			a := valStack[sp]
			if uint32(a) == 0 { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x46: // i32.eq
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if uint32(a) == uint32(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x47: // i32.ne
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if uint32(a) != uint32(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x48: // i32.lt_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if int32(a) < int32(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x49: // i32.lt_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if uint32(a) < uint32(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x4a: // i32.gt_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if int32(a) > int32(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x4b: // i32.gt_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if uint32(a) > uint32(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x4c: // i32.le_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if int32(a) <= int32(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x4d: // i32.le_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if uint32(a) <= uint32(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x4e: // i32.ge_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if int32(a) >= int32(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x4f: // i32.ge_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if uint32(a) >= uint32(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x50: // i64.eqz
			sp--
			a := valStack[sp]
			if a == 0 { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x51: // i64.eq
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if a == b { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x52: // i64.ne
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if a != b { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x53: // i64.lt_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if int64(a) < int64(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x54: // i64.lt_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if a < b { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x55: // i64.gt_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if int64(a) > int64(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x56: // i64.gt_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if a > b { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x57: // Bug 3 fix: i64.ge_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if int64(a) >= int64(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x58: // Bug 3 fix: i64.ge_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if a >= b { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x59: // Bug 3 fix: i64.le_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if int64(a) <= int64(b) { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x5a: // Bug 3 fix: i64.le_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			if a <= b { valStack[sp] = 1 } else { valStack[sp] = 0 }
			sp++
		case 0x67: // i32.clz
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(bits.LeadingZeros32(uint32(a)))
			sp++
		case 0x68: // i32.ctz
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(bits.TrailingZeros32(uint32(a)))
			sp++
		case 0x69: // i32.popcnt
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(bits.OnesCount32(uint32(a)))
			sp++
		case 0x6a: // i32.add
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(a) + uint32(b))
			sp++
		case 0x6b: // i32.sub
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(a) - uint32(b))
			sp++
		case 0x6c: // i32.mul
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(a) * uint32(b))
			sp++
		case 0x6d: // i32.div_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(int32(a) / int32(b)))
			sp++
		case 0x6e: // i32.div_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(a) / uint32(b))
			sp++
		case 0x6f: // Bug 3 fix: i32.rem_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(int32(a) % int32(b)))
			sp++
		case 0x70: // Bug 3 fix: i32.rem_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(a) % uint32(b))
			sp++
		case 0x71: // i32.and
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(a) & uint32(b))
			sp++
		case 0x72: // i32.or
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(a) | uint32(b))
			sp++
		case 0x73: // i32.xor
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(a) ^ uint32(b))
			sp++
		case 0x74: // i32.shl
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(a) << (uint32(b) & 31))
			sp++
		case 0x75: // i32.shr_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(int32(a) >> (uint32(b) & 31)))
			sp++
		case 0x76: // i32.shr_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(a) >> (uint32(b) & 31))
			sp++
		case 0x77: // Bug 3 fix: i32.rotl
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(bits.RotateLeft32(uint32(a), int(b)))
			sp++
		case 0x78: // Bug 3 fix: i32.rotr
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(bits.RotateLeft32(uint32(a), -int(b)))
			sp++
		case 0x79: // i64.clz
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(bits.LeadingZeros64(a))
			sp++
		case 0x7a: // i64.ctz
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(bits.TrailingZeros64(a))
			sp++
		case 0x7b: // i64.popcnt
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(bits.OnesCount64(a))
			sp++
		case 0x7c: // i64.add
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = a + b
			sp++
		case 0x7d: // i64.sub
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = a - b
			sp++
		case 0x7e: // i64.mul
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = a * b
			sp++
		case 0x7f: // i64.div_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(int64(a) / int64(b))
			sp++
		case 0x80: // i64.div_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = a / b
			sp++
		case 0x81: // Bug 3 fix: i64.rem_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(int64(a) % int64(b))
			sp++
		case 0x82: // Bug 3 fix: i64.rem_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = a % b
			sp++
		case 0x83: // i64.and
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = a & b
			sp++
		case 0x84: // i64.or
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = a | b
			sp++
		case 0x85: // i64.xor
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = a ^ b
			sp++
		case 0x86: // i64.shl
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = a << (b & 63)
			sp++
		case 0x87: // i64.shr_s
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(int64(a) >> (b & 63))
			sp++
		case 0x88: // i64.shr_u
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = a >> (b & 63)
			sp++
		case 0x89: // Bug 3 fix: i64.rotl
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = bits.RotateLeft64(a, int(b))
			sp++
		case 0x8a: // Bug 3 fix: i64.rotr
			sp--
			b := valStack[sp]
			sp--
			a := valStack[sp]
			valStack[sp] = bits.RotateLeft64(a, -int(b))
			sp++
		case 0xa7: // i32.wrap_i64
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(a))
			sp++
		case 0xac: // i64.extend_i32_s
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(int64(int32(a)))
			sp++
		case 0xad: // i64.extend_i32_u
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(uint32(a))
			sp++
		case 0xb7: // Bug 3 fix: f32.convert_i32_s
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(math.Float32bits(float32(int32(a))))
			sp++
		case 0xb8: // Bug 3 fix: f32.convert_i32_u
			sp--
			a := valStack[sp]
			valStack[sp] = uint64(math.Float32bits(float32(uint32(a))))
			sp++
		case 0xba: // f64.convert_i32_u
			sp--
			a := valStack[sp]
			valStack[sp] = math.Float64bits(float64(uint32(a)))
			sp++
		case 0xbd: // f64.convert_i64_u
			sp--
			a := valStack[sp]
			valStack[sp] = math.Float64bits(float64(a))
			sp++
		case 0xc1: // f64.promote_f32
			sp--
			a := valStack[sp]
			valStack[sp] = math.Float64bits(float64(math.Float32frombits(uint32(a))))
			sp++
		case 0xfc: // saturating float or memory operations
			sub := readLEB128uGen(code, &pos)
			if sub == 10 { // memory.fill
				pos += 2
				sp--
				n := valStack[sp]
				sp--
				val := valStack[sp]
				sp--
				ptr := valStack[sp]
				addr := int(uint32(ptr))
				ensureMem(addr + int(uint32(n)))
				for i := uint32(0); i < uint32(n); i++ {
					mem[addr+int(i)] = byte(val)
				}
			} else if sub == 11 { // memory.copy
				pos += 2
				sp--
				n := valStack[sp]
				sp--
				src := valStack[sp]
				sp--
				dst := valStack[sp]
				dstAddr := int(uint32(dst))
				srcAddr := int(uint32(src))
				count := int(uint32(n))
				ensureMem(dstAddr + count)
				ensureMem(srcAddr + count)
				copy(mem[dstAddr:dstAddr+count], mem[srcAddr:srcAddr+count])
			}
		default: // Bug 3 fix: panic on unimplemented opcode
			panic(fmt.Sprintf("unimplemented opcode 0x%02x at pos %d in fn %d", op, pos-1, fnIdx))
		}
	}

	vmStackPool.Put(spPtr)
	if sp > 0 {
		return valStack[sp-1]
	}
	return 0
}
type genMemory struct{ api.Memory }

func (m genMemory) Read(offset uint32, byteCount uint32) ([]byte, bool) {
	ensureMem(int(offset)+int(byteCount))
	res := make([]byte, byteCount)
	copy(res, mem[offset:offset+byteCount])
	return res, true
}

func (m genMemory) ReadByte(offset uint32) (byte, bool) {
	ensureMem(int(offset)+1)
	return mem[offset], true
}

func (m genMemory) ReadUint16Le(offset uint32) (uint16, bool) {
	ensureMem(int(offset)+2)
	return binary.LittleEndian.Uint16(mem[offset:]), true
}

func (m genMemory) ReadUint32Le(offset uint32) (uint32, bool) {
	ensureMem(int(offset)+4)
	return binary.LittleEndian.Uint32(mem[offset:]), true
}

func (m genMemory) ReadUint64Le(offset uint32) (uint64, bool) {
	ensureMem(int(offset)+8)
	return binary.LittleEndian.Uint64(mem[offset:]), true
}

func (m genMemory) ReadFloat32Le(offset uint32) (float32, bool) {
	ensureMem(int(offset)+4)
	return math.Float32frombits(binary.LittleEndian.Uint32(mem[offset:])), true
}

func (m genMemory) ReadFloat64Le(offset uint32) (float64, bool) {
	ensureMem(int(offset)+8)
	return math.Float64frombits(binary.LittleEndian.Uint64(mem[offset:])), true
}

func (m genMemory) Write(offset uint32, data []byte) bool {
	ensureMem(int(offset)+len(data))
	copy(mem[offset:], data)
	return true
}

func (m genMemory) WriteByte(offset uint32, val byte) bool {
	ensureMem(int(offset)+1)
	mem[offset] = val
	return true
}

func (m genMemory) WriteUint16Le(offset uint32, val uint16) bool {
	ensureMem(int(offset)+2)
	binary.LittleEndian.PutUint16(mem[offset:], val)
	return true
}

func (m genMemory) WriteUint32Le(offset uint32, val uint32) bool {
	ensureMem(int(offset)+4)
	binary.LittleEndian.PutUint32(mem[offset:], val)
	return true
}

func (m genMemory) WriteUint64Le(offset uint32, val uint64) bool {
	ensureMem(int(offset)+8)
	binary.LittleEndian.PutUint64(mem[offset:], val)
	return true
}

func (m genMemory) WriteFloat32Le(offset uint32, val float32) bool {
	ensureMem(int(offset)+4)
	binary.LittleEndian.PutUint32(mem[offset:], math.Float32bits(val))
	return true
}

func (m genMemory) WriteFloat64Le(offset uint32, val float64) bool {
	ensureMem(int(offset)+8)
	binary.LittleEndian.PutUint64(mem[offset:], math.Float64bits(val))
	return true
}

func (m genMemory) WriteString(offset uint32, val string) bool {
	ensureMem(int(offset)+len(val))
	copy(mem[offset:], val)
	return true
}

func (m genMemory) Size() uint32 { return uint32(len(mem)) }
func (m genMemory) Definition() api.MemoryDefinition { return nil }
func (m genMemory) PageSize() uint32 { return 65536 }
func (m genMemory) Grow(delta uint32) (uint32, bool) { return uint32(len(mem) / 65536), true }
func (m genMemory) wazeroOnly() {}

var genMemInstance genMemory

